-- Apply the category's default assignee in the database, so no live work order
-- is ever filed without an owner (Aravind, 2026-11-12: "nothing sits in the
-- queue without an owner").
--
-- The app already applies defaults when an administrator files a work order or
-- approves a submission with nobody picked. Occurrences generated by pg_cron
-- from a recurring schedule bypass the app and copy the schedule's assignee,
-- which is often empty, so they landed unassigned. This trigger covers every
-- insert path the same way: an IT request-type rule wins over the category
-- rule, matching resolveDefaultAssignee() in lib/work-orders/default-assignees.ts.
--
-- Pending submissions are left alone: the administrator picks the assignee at
-- approval, where the app applies the default.
--
-- Runs before the other BEFORE INSERT triggers (alphabetical order), so the
-- assignee name and same-organization checks see the assignee it picks.
--
-- Rollback:
--   drop trigger if exists work_orders_apply_default_assignee on public.work_orders;
--   drop function if exists public.apply_default_assignee();

create or replace function public.apply_default_assignee()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.assigned_to is null
     and new.status::text in ('open', 'assigned', 'in_progress', 'on_hold') then
    select d.user_id into new.assigned_to
    from public.default_assignees d
    where d.organization_id = new.organization_id
      and d.category = new.category
      and (d.it_request_type is null or d.it_request_type = new.it_request_type)
    order by (d.it_request_type is not null) desc
    limit 1;
  end if;
  return new;
end;
$$;

revoke all on function public.apply_default_assignee() from public, anon, authenticated;

create trigger work_orders_apply_default_assignee
  before insert on public.work_orders
  for each row execute function public.apply_default_assignee();
